import type { ReactNode } from "react";

import type { ScreenSlot } from "@/components/tennantite/lib/screen-types";
import { GuiSprite } from "@/components/tennantite/gui-sprite";
import { PlayerInventory } from "@/components/tennantite/player-inventory";
import { ScreenPanel } from "@/components/tennantite/screen-panel";
import { gui } from "@/components/tennantite/lib/tennantite-utils";
import { ScreenItemSlot } from "@/components/tennantite/lib/screen-slot";

export interface GrindstoneScreenProps {
  additional?: ScreenSlot;
  className?: string;
  error?: boolean;
  hotbarItems?: ScreenSlot[];
  input?: ScreenSlot;
  onSlotClick?: (area: "hotbar" | "input" | "main" | "output", index: number) => void;
  output?: ScreenSlot;
  selectedIndex?: number;
  title?: ReactNode;
}

/**
 * 砂轮界面（规格 §6）：`container/grindstone.png` 176×166。
 */
const EMPTY_HOTBAR_ITEMS: ScreenSlot[] = [];
export function GrindstoneScreen({
  additional,
  className,
  error = false,
  hotbarItems = EMPTY_HOTBAR_ITEMS,
  input,
  onSlotClick,
  output,
  selectedIndex,
  title,
}: GrindstoneScreenProps) {
  return (
    <ScreenPanel
      background="container/grindstone.png"
      className={className}
      height={166}
      title={title}
      width={176}
    >
      <ScreenItemSlot
        item={input}
        label="grindstone-input"
        left={48}
        onActivate={onSlotClick ? () => onSlotClick("input", 0) : undefined}
        top={18}
      />
      <ScreenItemSlot
        item={additional}
        label="grindstone-additional"
        left={48}
        onActivate={onSlotClick ? () => onSlotClick("input", 1) : undefined}
        top={39}
      />
      <ScreenItemSlot
        item={output}
        label="grindstone-output"
        left={128}
        onActivate={onSlotClick ? () => onSlotClick("output", 0) : undefined}
        top={33}
      />
      {error
        ? (
            <GuiSprite
              className="absolute"
              height={21}
              name="sprites/container/grindstone/error.png"
              style={{ left: gui(92), top: gui(31) }}
              width={28}
            />
          )
        : null}
      <PlayerInventory
        bare
        hotbarItems={hotbarItems}
        onSlotClick={onSlotClick}
        selectedIndex={selectedIndex}
      />
    </ScreenPanel>
  );
}
